// === Tab: mySketch ===
let theShader = null;

function preload() {
	theShader = createShader(vert, frag);
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	background(100);
	rectMode(CENTER);
}

function draw() {
	shader(theShader);
	background(0);
	theShader.setUniform('u_resolution', [width, height]);
	theShader.setUniform('u_time', millis() / 100);

	rect(0, 0, width, height);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

// === Tab: vert ===
const vert = `
	#ifdef GL_ES
  	precision highp float;
    precision highp int;
  #endif

	// attribute, in
	attribute vec3 aNormal;
	attribute vec3 aPosition;
	attribute vec2 aTexTCoord;
	attribute vec4 aVerTextColor;

	// attributes, out
	varying vec3 var_vertNormal;
	varying vec3 var_vertPosition;
	varying vec2 var_vertTexTCoord;
	varying vec4 var_vertTextColor;

	// matrices
	uniform mat3 uNormalMatrix;
	uniform mat4 uModelViewMatrix;
	uniform mat4 uProjectionMatrix;

	void main() {
		vec4 mvPosition = uModelViewMatrix * vec4(aPosition, 1.0);

		gl_Position = uProjectionMatrix * mvPosition;
	}
`;

// === Tab: frag ===
const frag = `
	#ifdef GL_ES
		precision highp float;
	#endif

	uniform vec2 u_resolution;
	uniform float u_time;

	//attributes, in
	varying vec2 var_vartUv;

	void main(void)
	{
			vec2 position = - 1.0 + 2.0 * gl_FragCoord.xy / u_resolution;

			float red = abs(sin(position.x * position.y + u_time / 5.0));
			float green = abs(sin(position.x * position.y + u_time / 4.0));
			float blue = abs(sin(position.x * position.y + u_time / 3.0));


			gl_FragColor = vec4(red, green, blue, 5.0);
	}
`;

